get_dashboard_report_quick.code:
const response = await client.dashboardReports.getDashboardReportQuick({duration: 'last_12_months', kpis: 'total_sales,aov', entity_name: 'product'});
console.log(response.map.orders.count, response.map.sales.total, response.map.sales.average_order_value);
for (const kpi of response.map.kpis) {
    console.log(kpi.key, kpi.value, kpi.change_percent);
}

get_dashboard_report_sales.code:
const response = await client.dashboardReports.getDashboardReportSales({duration: 'last_12_months', breakdown: 'true', sort: 'sales', order: 'desc'});
for (const row of response.map.rows) {
    console.log(row.date, row.label, row.sales);
}
console.log(response.map.totals.sales);

